// Agrupa as linhas da planilha por cliente e monta o HTML da fatura.
// As linhas viram markup aqui, e não no template, porque o motor de template
// do lado do servidor substitui valores mas não faz laço — um motor que
// avalia expressão vira superfície de execução remota quando o template vem
// de fora.

const escape = (v) => String(v ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const money = (n) => Number(n || 0).toLocaleString('en-US', {
  minimumFractionDigits: 2, maximumFractionDigits: 2,
});

// Uma fatura por cliente, somando todas as linhas dele no período.
const byClient = new Map();

for (const item of $input.all()) {
  const r = item.json;
  const key = r.client_email || r.client || 'unknown';
  if (!byClient.has(key)) {
    byClient.set(key, { client: r.client, email: r.client_email, rows: [] });
  }
  byClient.get(key).rows.push(r);
}

const period = new Date();
period.setMonth(period.getMonth() - 1);
const periodLabel = period.toLocaleString('en-US', { month: 'long', year: 'numeric' });

// Vencimento: era uma expressão $now.plus() no corpo do HTTP, que nunca chegou
// a ser avaliada. Calculado aqui, com os mesmos dias de prazo do Set node.
const termsDays = Number($('Set invoice defaults').first().json.payment_terms_days || 14);
const dueDate = new Date(Date.now() + termsDays * 86400000);
const dueLabel = dueDate.toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' });

const PDF_TEMPLATE = "<!doctype html><html><head><meta charset=\"utf-8\"><style>@page{size:A4;margin:18mm 16mm 20mm}body{font-family:'Open Sans',sans-serif;color:#1f1c19;font-size:12.5px;line-height:1.5;margin:0}header{display:flex;justify-content:space-between;border-bottom:2px solid #1f1c19;padding-bottom:12px;margin-bottom:20px}.brand{font-size:19px;font-weight:bold}.meta{text-align:right;font-size:11.5px;color:#5c534b}.label{font-size:8.5px;letter-spacing:.14em;text-transform:uppercase;color:#6b625b;margin-bottom:4px}table{width:100%;border-collapse:collapse}thead{display:table-header-group}tr{break-inside:avoid}th{text-align:left;font-size:8.5px;letter-spacing:.12em;text-transform:uppercase;color:#6b625b;border-bottom:1px solid #d8d2ca;padding:0 0 6px;font-weight:normal}td{padding:8px 0;border-bottom:1px solid #f2eee9;vertical-align:top}.num{text-align:right;white-space:nowrap}.totals{margin:18px 0 0 auto;width:54%;break-inside:avoid}.totals td{border:0;padding:5px 0}.totals .grand td{border-top:2px solid #1f1c19;padding-top:9px;font-size:15px;font-weight:bold}</style></head><body><header><div class=\"brand\">{{company.name}}</div><div class=\"meta\"><div><b>Invoice {{invoice_number}}</b></div><div>{{period}}</div><div>Due {{due_date}}</div></div></header><div class=\"label\">Billed to</div><p><b>{{client}}</b><br>{{client_email}}</p><table><thead><tr><th>Description</th><th class=\"num\">Qty</th><th class=\"num\">Unit</th><th class=\"num\">Amount</th></tr></thead><tbody>{{{rows_html}}}</tbody></table><table class=\"totals\"><tr><td>Subtotal</td><td class=\"num\">{{subtotal}}</td></tr><tr><td>{{tax_label}}</td><td class=\"num\">{{tax}}</td></tr><tr class=\"grand\"><td>Total due</td><td class=\"num\">{{total}}</td></tr></table></body></html>";

const out = [];
let seq = 0;

for (const [, group] of byClient) {
  seq += 1;

  let subtotal = 0;
  const rowsHtml = group.rows.map((r) => {
    const amount = Number(r.qty || 0) * Number(r.unit_price || 0);
    subtotal += amount;
    return `<tr>
      <td>${escape(r.description)}</td>
      <td class="num">${escape(r.qty)}</td>
      <td class="num">${money(r.unit_price)}</td>
      <td class="num">${money(amount)}</td>
    </tr>`;
  }).join('');

  const taxRate = Number($('Set invoice defaults').first().json.tax_rate || 0);
  const tax = subtotal * taxRate;

  const fields = {
    invoice_number: `${period.getFullYear()}${String(period.getMonth() + 1).padStart(2, '0')}-${String(seq).padStart(3, '0')}`,
    client: group.client,
    client_email: group.email,
    period: periodLabel,
    due_date: dueLabel,
    rows_html: rowsHtml,
    subtotal: money(subtotal),
    tax_label: `Tax (${(taxRate * 100).toFixed(0)}%)`,
    tax: money(tax),
    total: money(subtotal + tax),
    line_count: group.rows.length,
  };

  // ---------------------------------------------------------------------------
  // O pedido de PDF é montado aqui, não no nó HTTP.
  //
  // Motivo: um corpo JSON escrito à mão com "={{ ... }}" dentro das aspas não é
  // expressão para o n8n — só é expressão o campo cujo valor INTEIRO começa com
  // "=". Escrito daquele jeito, o texto cru {{ $json.rows_html }} era enviado à
  // API e saía impresso na página. Montando o objeto aqui e mandando um único
  // JSON.stringify, cada aspa de rows_html chega intacta.
  out.push({
    json: {
      ...fields,
      pdf_template: PDF_TEMPLATE,
      pdf_data: {
        company: { name: $('Set invoice defaults').first().json.company_name },
        ...fields,
      },
    },
  });
}

return out;
